5	/* Check sizes as listed in the .xz file format specification.  Only the
6	 * IDs 0 (None), 1 (CRC32), 4 (CRC64) and 10 (SHA-256) are implemented,
7	 * but the sizes of the reserved IDs are needed to skip over unsupported
8	 * check fields while decoding. */
9	const uint8_t xr_check_sizes[16] = {
10		0,
11		4, 4, 4,
12		8, 8, 8,
13		16, 16, 16,
14		32, 32, 32,
15		64, 64, 64
16	};
17	
18	void xr_check_init(xr_check_state *check, uint32_t type)
19	{
20		switch (type) {
21		case XR_CHECK_NONE:
22			break;
23	
24		case XR_CHECK_CRC32:
25			check->state.crc32 = 0;
26			break;
27	
28		case XR_CHECK_CRC64:
29			check->state.crc64 = 0;
30			break;
31	
32		case XR_CHECK_SHA256:
33			xr_sha256_init(check);
34			break;
35	
36		default:
37			break;
38		}
39	}
40	
41	void xr_check_update(xr_check_state *check, uint32_t type,
42			const uint8_t *buf, size_t size)
43	{
44		switch (type) {
45		case XR_CHECK_CRC32:
46			check->state.crc32 = xr_crc32(buf, size, check->state.crc32);
47			break;
48	
49		case XR_CHECK_CRC64:
50			check->state.crc64 = xr_crc64(buf, size, check->state.crc64);
51			break;
52	
53		case XR_CHECK_SHA256:
54			xr_sha256_update(buf, size, check);
55			break;
56	
57		default:
58			break;
59		}
60	}
61	
62	void xr_check_finish(xr_check_state *check, uint32_t type)
63	{
64		switch (type) {
65		case XR_CHECK_CRC32:
66			xr_write32le(check->buffer.u8, check->state.crc32);
67			break;
68	
69		case XR_CHECK_CRC64:
70			xr_write64le(check->buffer.u8, check->state.crc64);
71			break;
72	
73		case XR_CHECK_SHA256:
74			xr_sha256_finish(check);
75			break;
76	
77		default:
78			break;
79		}
80	}
