199	{
200		const xr_options_lzma *options = opt;
201	
202		if (lz->coder == NULL) {
203			lzma2_dec *coder = calloc(1, sizeof(lzma2_dec));
204			if (coder == NULL)
205				return XR_MEM_ERROR;
206			coder->lzma = malloc(xr_lzma_dec_size());
207			if (coder->lzma == NULL) {
208				free(coder);
209				return XR_MEM_ERROR;
