4	typedef struct {
5		xr_dict dict;
6		xr_lz_decoder lz;
7	} lz_coder;
8	
9	static xr_ret lz_decode(void *coder_ptr, const uint8_t *restrict in,
10			size_t *restrict in_pos, size_t in_size,
11			uint8_t *restrict out, size_t *restrict out_pos,
12			size_t out_size, xr_action action)
13	{
14		lz_coder *coder = coder_ptr;
15		const bool eof = (action == XR_FINISH);
16	
17		while (true) {
18			const size_t dict_start = coder->dict.pos;
19			const size_t out_avail = out_size - *out_pos;
20			size_t room = coder->dict.size - coder->dict.pos;
21			if (room > out_avail)
22				room = out_avail;
23	
24			coder->dict.limit = coder->dict.pos + room;
25	
26			const xr_ret ret = coder->lz.code(coder->lz.coder, &coder->dict,
27					in, in_pos, in_size, eof);
28	
29			const size_t copy_size = coder->dict.pos - dict_start;
30			if (copy_size > 0) {
31				memcpy(out + *out_pos, coder->dict.buf + dict_start,
32						copy_size);
33				*out_pos += copy_size;
34			}
35	
36			if (coder->dict.pos == coder->dict.size)
37				coder->dict.pos = 0;
38	
39			if (ret != XR_OK)
40				return ret;
41	
42			if (*out_pos == out_size)
43				return XR_OK;
44	
45			/* If nothing was produced and no input consumed, we need more
46			 * input from the caller. */
47			if (copy_size == 0)
48				return XR_OK;
49		}
50	}
51	
52	static void lz_decoder_end(void *coder_ptr)
53	{
54		lz_coder *coder = coder_ptr;
55		free(coder->dict.buf);
56		if (coder->lz.end != NULL)
57			coder->lz.end(coder->lz.coder);
58		else
59			free(coder->lz.coder);
60		free(coder);
61	}
62	
63	uint64_t xr_lz_decoder_memusage(uint64_t dict_size)
64	{
65		return sizeof(lz_coder) + dict_size;
66	}
67	
68	xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
69			xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
70				const void *options))
71	{
72		lz_coder *coder = next->coder;
73	
74		if (coder == NULL || next->code != &lz_decode) {
75			coder = calloc(1, sizeof(lz_coder));
76			if (coder == NULL)
77				return XR_MEM_ERROR;
78			next->coder = coder;
79			next->code = &lz_decode;
80			next->end = &lz_decoder_end;
81		}
82	
83		xr_lz_options lz_options;
84		memset(&lz_options, 0, sizeof(lz_options));
85		const xr_ret ret = lz_init(&coder->lz, &lz_options, filters[0].options);
86		if (ret != XR_OK)
87			return ret;
88	
89		if (lz_options.dict_size < 4096)
90			lz_options.dict_size = 4096;
91		lz_options.dict_size = (lz_options.dict_size + 15) & ~(size_t)15;
92	
93		if (coder->dict.buf == NULL || coder->dict.size != lz_options.dict_size) {
94			free(coder->dict.buf);
95			coder->dict.buf = malloc(lz_options.dict_size);
96			if (coder->dict.buf == NULL) {
97				coder->dict.size = 0;
98				return XR_MEM_ERROR;
99			}
100			coder->dict.size = lz_options.dict_size;
101		}
102	
103		xr_dict_reset(&coder->dict);
104	
105		if (lz_options.preset_dict != NULL && lz_options.preset_dict_size > 0) {
106			size_t copy = lz_options.preset_dict_size;
107			if (copy > lz_options.dict_size)
108				copy = lz_options.dict_size;
109			memcpy(coder->dict.buf, lz_options.preset_dict
110					+ lz_options.preset_dict_size - copy, copy);
111			coder->dict.pos = copy;
112			coder->dict.full = copy;
113		}
114	
115		return XR_OK;
